procedures.OBJOBJ_SEL:
declare variable MINDATUM date;
declare variable MAXDATUM date;
declare variable ROZDIL integer;
begin
  for select
  IDOBJ,IDPAC,IDPRAC,DATUM,CAS,TYP,PRISEL,INFO,ODESLEKAR,OPERATER,DIAGNOZA,PLANVYKON,POZNAMKA,IDUZI,DATUMDO,CASDO,REZERVACE,DATZAPIS,COLORID,
  CELEJMENO,RODCIS,POJ,IDREC,TYPPROH,IDEXT,IDCAL_EXT,COS_PAC,CREATEDBY,CREATED,IDCINNOSTI,IDZARAZENI,CHANGED,PIN,ES_APPID,ES_UID,ES_ODESLANO,
  ES_RESYNC_NEEDED,ES_TASK_ID,WEBCAL_UID,WEBCAL_SYNC,GUID,TELEFON,CEKATEL
  from OBJOBJ where ((IDOBJ = :AIDOBJ) or (:AIDOBJ is null)) and ((IDPAC = :AIDPAC) or (:AIDPAC is null)) and ((IDPRAC = :AIDPRAC) or (:AIDPRAC is null))
  and not (TYP in (9, 10)) and ((IDUZI = :AIDUZI) or (:AIDUZI is null)) and (DATUM >= :ADATUMOD) and (DATUM <= :ADATUMDO) into
  :IDOBJ,:IDPAC,:IDPRAC,:DATUM,:CAS,:TYP,:PRISEL,:INFO,:ODESLEKAR,:OPERATER,:DIAGNOZA,:PLANVYKON,:POZNAMKA,:IDUZI,:DATUMDO,:CASDO,:REZERVACE,:DATZAPIS,:COLORID,
  :CELEJMENO,:RODCIS,:POJ,:IDREC,:TYPPROH,:IDEXT,:IDCAL_EXT,:COS_PAC,:CREATEDBY,:CREATED,:IDCINNOSTI,:IDZARAZENI,:CHANGED,:PIN,:ES_APPID,:ES_UID,:ES_ODESLANO,
  :ES_RESYNC_NEEDED,:ES_TASK_ID,:WEBCAL_UID,:WEBCAL_SYNC,:GUID,:TELEFON,:CEKATEL do
  begin
    suspend;
  end
  /* pravidelna objednavka - kazdy den v tydnu */
  for select
  IDOBJ,IDPAC,IDPRAC,DATUM,CAS,TYP,PRISEL,INFO,ODESLEKAR,OPERATER,DIAGNOZA,PLANVYKON,POZNAMKA,IDUZI,DATUMDO,CASDO,REZERVACE,DATZAPIS,COLORID,
  CELEJMENO,RODCIS,POJ,IDREC,TYPPROH,IDEXT,IDCAL_EXT,COS_PAC,CREATEDBY,CREATED,IDCINNOSTI,IDZARAZENI,CHANGED,PIN,ES_APPID,ES_UID,ES_ODESLANO,
  ES_RESYNC_NEEDED,ES_TASK_ID,WEBCAL_UID,WEBCAL_SYNC,GUID,TELEFON,CEKATEL
  from OBJOBJ where ((IDOBJ = :AIDOBJ) or (:AIDOBJ is null)) and ((IDPAC = :AIDPAC) or (:AIDPAC is null)) and ((IDPRAC = :AIDPRAC) or (:AIDPRAC is null))
  and ((IDUZI = :AIDUZI) or (:AIDUZI is null)) and (DATUM <= :ADATUMDO) and (DATUMDO >= :ADATUMOD) and (TYP = 9) into
  :IDOBJ,:IDPAC,:IDPRAC,:DATUM,:CAS,:TYP,:PRISEL,:INFO,:ODESLEKAR,:OPERATER,:DIAGNOZA,:PLANVYKON,:POZNAMKA,:IDUZI,:DATUMDO,:CASDO,:REZERVACE,:DATZAPIS,:COLORID,
  :CELEJMENO,:RODCIS,:POJ,:IDREC,:TYPPROH,:IDEXT,:IDCAL_EXT,:COS_PAC,:CREATEDBY,:CREATED,:IDCINNOSTI,:IDZARAZENI,:CHANGED,:PIN,:ES_APPID,:ES_UID,:ES_ODESLANO,
  :ES_RESYNC_NEEDED,:ES_TASK_ID,:WEBCAL_UID,:WEBCAL_SYNC,:GUID,:TELEFON,:CEKATEL do
  begin
    MINDATUM = DATUM;
    if (MINDATUM < ADATUMOD) then
      MINDATUM = ADATUMOD;
    MAXDATUM = DATUMDO;
    if (MAXDATUM > ADATUMDO) then
      MAXDATUM = ADATUMDO;
    while (MINDATUM <= MAXDATUM) do
    begin
      DATUM = MINDATUM;
      suspend;
      MINDATUM = MINDATUM + 1;
    end
  end
  /* pravidelna objednavka - jen stejny den v tydnu */
  for select
  IDOBJ,IDPAC,IDPRAC,DATUM,CAS,TYP,PRISEL,INFO,ODESLEKAR,OPERATER,DIAGNOZA,PLANVYKON,POZNAMKA,IDUZI,DATUMDO,CASDO,REZERVACE,DATZAPIS,COLORID,
  CELEJMENO,RODCIS,POJ,IDREC,TYPPROH,IDEXT,IDCAL_EXT,COS_PAC,CREATEDBY,CREATED,IDCINNOSTI,IDZARAZENI,CHANGED,PIN,ES_APPID,ES_UID,ES_ODESLANO,
  ES_RESYNC_NEEDED,ES_TASK_ID,WEBCAL_UID,WEBCAL_SYNC,GUID,TELEFON,CEKATEL
  from OBJOBJ where ((IDOBJ = :AIDOBJ) or (:AIDOBJ is null)) and ((IDPAC = :AIDPAC) or (:AIDPAC is null)) and ((IDPRAC = :AIDPRAC) or (:AIDPRAC is null))
  and ((IDUZI = :AIDUZI) or (:AIDUZI is null)) and (DATUM <= :ADATUMDO) and (DATUMDO >= :ADATUMOD) and (TYP = 10) into
  :IDOBJ,:IDPAC,:IDPRAC,:DATUM,:CAS,:TYP,:PRISEL,:INFO,:ODESLEKAR,:OPERATER,:DIAGNOZA,:PLANVYKON,:POZNAMKA,:IDUZI,:DATUMDO,:CASDO,:REZERVACE,:DATZAPIS,:COLORID,
  :CELEJMENO,:RODCIS,:POJ,:IDREC,:TYPPROH,:IDEXT,:IDCAL_EXT,:COS_PAC,:CREATEDBY,:CREATED,:IDCINNOSTI,:IDZARAZENI,:CHANGED,:PIN,:ES_APPID,:ES_UID,:ES_ODESLANO,
  :ES_RESYNC_NEEDED,:ES_TASK_ID,:WEBCAL_UID,:WEBCAL_SYNC,:GUID,:TELEFON,:CEKATEL do
  begin
    MINDATUM = DATUM;
    /* pokud pravidelna tydenni objednavka zacina pred rozhodnym datem, musime jeji zacatek nastavit na datum, ktere odpovida prislusnemu dni v tydnu */
    if (MINDATUM < ADATUMOD) then
    begin
      ROZDIL = MOD(ADATUMOD - MINDATUM, 7);
      if (ROZDIL = 0) then
        MINDATUM = ADATUMOD;
      else
        MINDATUM = ADATUMOD + 7 - ROZDIL;
    end
    MAXDATUM = DATUMDO;
    if (MAXDATUM > ADATUMDO) then
      MAXDATUM = ADATUMDO;
    while (MINDATUM <= MAXDATUM) do
    begin
      DATUM = MINDATUM;
      suspend;
      MINDATUM = MINDATUM + 7;
    end
  end
end

